// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.skill.router/** * NOUS — Permission checker interface. * * Brain uses this to check if permissions are granted before executing skills. * Real implementation: [com.roshan.persona.security.integrity.RealPermissionChecker] * in :feature:security — wraps `ContextCompat.checkSelfPermission`. * * Test fake: `FakePermissionChecker` in `src/test/kotlin/.../skill/router/`. * * @see <a href="docs/spec/module2-spec-review.pdf">§6.1 Permission Fix</a> */interface PermissionChecker {    /** Check if a single permission is granted. */    fun isGranted(permission: String): Boolean    /** Check if ALL permissions in a set are granted. */    fun areAllGranted(permissions: Set<String>): Boolean {        return permissions.all { isGranted(it) }    }    /** Return the subset of permissions that are NOT granted. */    fun findMissing(permissions: Set<String>): Set<String> {        return permissions.filterNot { isGranted(it) }.toSet()    }}